var t=[{title:`Een startkader`,text:`Lage herhalingsbereiken, vaak ongeveer een tot vijf per set, horen meestal bij zwaardere gewichten en veel rust voor het oefenen van maximale kracht. Matige bereiken, grofweg zes tot twaalf, maken het makkelijk om een stevig gewicht, techniekcontrole en totaal werk te combineren. Hogere bereiken, zoals vijftien of meer, kunnen helpen bij lokaal spieruithoudingsvermogen en training met lagere gewichten.`},{title:`Waarom de bereiken overlappen`,text:`Onderzoek ondersteunt niet het idee dat zes tot twaalf herhalingen de enige manier zijn om spieren op te bouwen, of dat vijftien herhalingen geen kracht kunnen opbouwen. Zware belasting werkt vooral goed om de maximale eenherhalingskracht te verbeteren, terwijl spieren over een breed bereik van gewichten kunnen groeien als inspanning en volume hoog genoeg zijn. Heel veel herhalingen kunnen worden afgebroken door ongemak of door hart- en longvermoeidheid voordat de doelspier genoeg wordt uitgedaagd.`},{title:`Het bereik afstemmen op de oefening`,text:`Een zware samengestelde oefening is misschien makkelijker te beheersen met minder herhalingen. Een squat met lichaamsgewicht heeft misschien meer herhalingen nodig voordat hij zwaar wordt. Een plank wordt meestal gemeten aan hoe lang je hem vasthoudt. De beoogde bewegingskwaliteit, veiligheid, de gewichten die je hebt en je uitrusting moeten de keuze sturen.`},{title:`Voorbeeld`,text:`Een beginner kan 2–3 sets van 8–12 goblet squats, roeibewegingen en persen doen en een paar herhalingen in reserve houden. Als dezelfde weerstand makkelijk wordt voor twaalf herhalingen, verhoog dan het gewicht iets of kies een zwaardere variant. Iemand die zich later op kracht richt, kan meer sets van minder herhalingen doen bij gekozen oefeningen.`},{title:`Veelgemaakte fout`,text:`Een herhalingsdoel betekent weinig als je negeert hoe dicht de set bij een zware inspanning komt. Tien moeiteloze herhalingen en tien herhalingen bij je limiet zijn verschillende doseringen training.`},{title:`TrainUp gebruiken`,text:`Het schema geeft elke oefening een herhalingsdoel of een houdtijd, en jij kiest het gewicht. Als je het schema opnieuw genereert, kijkt het naar je inspanningsscores en hoeveel van elke training je hebt afgemaakt. Als je laatste 4 trainingen makkelijk waren (RPE 5 of lager) en compleet, wordt het volgende schema een stap zwaarder.`}];var i=[{label:`Overzicht van het herhalingscontinuüm`,url:`https://pubmed.ncbi.nlm.nih.gov/33671664/`},{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};